<template>
    <div>
      <v-text-field
        v-model="projectName"
        label="Enter Project Name"
        @input="resetProgress"
      ></v-text-field>
      <v-btn @click="checkForDuplicates">Check for Duplicates</v-btn>
      
      <!-- Progress Bar -->
      <v-progress-linear :value="progress" height="10" color="blue" v-if="isChecking">
        <template v-slot:default>
          {{ Math.round(progress) }}%
        </template>
      </v-progress-linear>
  
      <!-- Display Duplicates -->
      <div v-if="duplicates.length > 0">
        <h3>Duplicate Phone Numbers</h3>
        <ul>
          <li v-for="(duplicate, index) in duplicates" :key="index">
            {{ duplicate.phoneNumber }} - {{ duplicate.count }} duplicates
          </li>
        </ul>
      </div>
      <div v-else-if="!isChecking">No duplicates found.</div>
    </div>
  </template>
  
  <script>
  
  import { loadContacts } from '../utils/contactUtils';
  
  export default {
    data() {
      return {
        projectName: '',
        duplicates: [],
        progress: 0,
        isChecking: false,
      };
    },
    methods: {
      resetProgress() {
        this.progress = 0;
        this.duplicates = [];
      },
      async checkForDuplicates() {
        if (!this.projectName) return;
  
        this.isChecking = true;
        this.progress = 0;
  
        try {
          // Load all contacts for the project
          const contacts = await loadContacts(this.projectName,0);
          const totalContacts = contacts.length;
  
          // Count duplicates
          const phoneMap = {};
          contacts.forEach((contact, index) => {
            const phoneNumber = contact.phoneNumber;
            if (phoneNumber) {
              if (!phoneMap[phoneNumber]) {
                phoneMap[phoneNumber] = { count: 1 };
              } else {
                phoneMap[phoneNumber].count += 1;
              }
            }
  
            // Update progress
            this.progress = ((index + 1) / totalContacts) * 100;
          });
  
          // Filter only duplicated phone numbers
          this.duplicates = Object.keys(phoneMap)
            .filter(phone => phoneMap[phone].count > 1)
            .map(phone => ({
              phoneNumber: phone,
              count: phoneMap[phone].count,
            }));
  
        } catch (error) {
          console.error('Error checking duplicates:', error);
        } finally {
          this.isChecking = false;
        }
      },
    },
  };
  </script>
  
  <style scoped>
  /* Optional: Customize progress bar appearance */
  </style>
  