<template>
    <meta charset="UTF-8">
    <div class="light-blue-background">
        <h1>(v1.00) Project View for {{ projectName }}</h1>
        <div v-if="projects[0] && projects[0].presentations">
            <h1>Power Slide</h1>
            <powerSlide :presentation="projects[0].presentations" />
        </div>
        <!-- <h1>High Lights</h1>
        <div v-if="projects[0] && projects[0].highLights">
            <div v-for="item in projects[0].highLights" :key="item.description">
                <p>{{ item.description }}</p>
            </div>
        </div> -->

        <div class="highlights-section">
            <h1>High Lights</h1>
            <div v-if="hasHighlights">
                <div v-for="(item, index) in projects[0].highLights" :key="index + '-' + sanitizeKey(item.description)"
                    class="highlight-item">
                    <p v-if="item.description" class="highlight-text">
                        <span v-for="(line, lineIndex) in splitLines(item.description)" :key="lineIndex">
                            {{ line }}
                            <br v-if="lineIndex < splitLines(item.description).length - 1">
                        </span>
                    </p>
                    <p v-else class="empty-description">No description available</p>
                </div>
            </div>
            <div v-else class="no-highlights">
                <p>No highlights available for this project</p>
            </div>
        </div>

        <h1>Facilities & Amenities</h1>
        <div v-if="projects[0]" v-html="projects[0].facility"></div>


        <table>
            <thead>
                <tr>
                    <!-- Clicking this row will toggle the additional fields -->
                    <th @click="toggleExpanded">Project Name</th>

                    <th @click="toggleExpanded">Category</th>
                    <th @click="toggleExpanded">Developer</th>
                    <th @click="toggleExpanded">Completion Date</th>

                    <th title="Master, strata or individual titles." @click="toggleExpanded">Title Type</th>

                    <th title="Freehold, Leasehold" @click="toggleExpanded">Tenure</th>
                    <th @click="toggleExpanded">Year Built</th>
                    <th @click="toggleExpanded" class="table-column-width-3">Location</th>
                    <th @click="toggleExpanded">Land Dimension</th>





                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>


                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">3*No data available</td>
                </tr>
                <!-- 
                <tr v-for="project in projects" :key="project.id">

                    <td>{{project.projectName}}-----------------------</td>

                   
                </tr> -->


                <tr v-for="project in projects" :key="project.id">
                    <td>{{ project.projectName }}</td>

                    <td width="5%">{{ project.category }}</td>
                    <td>{{ project.developer }}</td>
                    <td>{{ project.completionDate || 'N/A' }}</td>
                    <td>{{ project.titleType }}</td>

                    <td>{{ project.tenure }}</td>
                    <td>{{ project.yearBuild }}</td>
                    <td width="30%">{{ project.location }}</td>
                    <td>{{ project.landDimension }}</td>







                    <td>
                        <button @click="editProject(project)">Edit</button>
                        <button @click="deleteProject(project)">Delete</button>
                    </td>
                </tr>
                <tr v-if="projects[0] && projects[0].furtherInformation">
                    <td colspan="9">
                        <p>Further Information:</p>
                        <p v-html="projects[0].furtherInformation"></p>
                    </td>
                </tr>
                <!-- Expandable unit details -->

            </tbody>
        </table>
        <table>
            <thead>
                <tr>
                    <!--                                                
                   
                    propertyType
                    projectUrl
                    DocUrl
                    lotStatus -->
                    <!-- Clicking this row will toggle the additional fields -->

                    <th title="Service Residence,Apartment,Condominium,Shop / Office,shop,Bungalow House,2-storey Terraced House,3-storey Terraced House"
                        @click="toggleExpanded">propertyType</th>
                    <th @click="toggleExpanded">projectUrl</th>
                    <th @click="toggleExpanded">Price Range</th>

                    <th @click="toggleExpanded">Size Range</th>


                    <th @click="toggleExpanded">Rental Range</th>


                    <th @click="toggleExpanded">DocUrl</th>
                    <th @click="toggleExpanded">Lot Status</th>

                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>
                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">2*No data available</td>
                </tr>
                <tr v-for="project in projects" :key="project.id">


                    <td>{{ project.propertyType }}</td>
                    <td>{{ project.projectUrl }}</td>
                    <td>{{ project.priceRange }}</td>
                    <td>{{ project.sizeRange }}</td>
                    <td>{{ project.rentalRange }}</td>

                    <td>{{ project.DocUrl || 'N/A' }}</td>
                    <td>{{ project.lotStatus || 'N/A' }}</td>

                </tr>

                <!-- Expandable unit details -->

            </tbody>
        </table>
        <table>
            <thead>
                <tr>
                    <!-- Clicking this row will toggle the additional fields -->

                    <th @click="toggleExpanded">Description</th>

                </tr>
                <!-- Conditionally render additional header fields when expanded is true -->

            </thead>
            <tbody>
                <tr v-if="projects.length === 0">
                    <td colspan="6" class="text-center">1*No data available</td>
                </tr>

                <tr v-for="project in projects" :key="project.id">


                    <td v-html="project.description"></td>

                    <td>
                        <button @click="editProject(project)">Edit</button>
                        <button @click="deleteProject(project)">Delete</button>
                    </td>
                </tr>

                <!-- Expandable unit details -->

            </tbody>
        </table>

        <table v-if="expanded">
            <tbody>
                <tr>
                    <td>Not Yet Implement</td>
                </tr>
            </tbody>
        </table>
        <template v-for="project in projects" :key="project.id">
            <tr v-if="project.layouts.length > 0">
                <td colspan="6">
                    <table>
                        <thead>
                            <tr>
                                <th>image</th>
                                <th>Type</th>
                                <th>Unit No</th>
                                <th>Bed Rooms</th>
                                <th>Bathrooms</th>
                                <th>Car Parks</th>
                                <th>Build Up Area</th>
                                <th>Has Balcony</th>

                                <th>Market Price</th>
                                <th>Transacted Date & Price</th>

                                <th>Developer Price</th>
                                <th>Rental</th>
                            </tr>
                        </thead>
                        <tbody>

                            <tr v-for="unit in project.layouts" :key="unit.name">

                                <!-- <td v-for="unit2 in unit.image.data" :key="unit2.attributes.url">
                                    <img :src="unit2.attributes.url.replace('upload/', 'upload/w_200/')" />
                                </td>     -->

                                <td v-if="unit.image && unit.image.data && unit.image.data.length > 0">
                                    <img :src="unit.image.data[0].attributes.url.replace('upload/', 'upload/w_200/')"
                                        @click="showImageModal(unit.image.data[0].attributes.url)"
                                        style="width: 200px; height: 150px; object-fit: cover;" />
                                </td>
                                <td v-else>
                                    <div style="width: 200px; height: 150px;"></div>
                                </td>


                                <td>{{ unit.type }}</td>

                                <td>{{ unit.unitNo }}</td>
                                <td>{{ unit.bedroom }}</td>
                                <td>{{ unit.bathroom }}</td>
                                <td>{{ unit.carpark }}</td>
                                <td>{{ unit.builtUp }} sq ft</td>
                                <td>{{ unit.hasBalcony }}</td>
                                <td>{{ unit.price }}</td>
                                <td>{{ unit.transactedDatePrice }}</td>

                                <td>
                                    <table>
                                        <!-- <thead>
                                            <tr>
                                                <th>{{ label1 }}</th>
                                                <th>{{ label2 }}</th>
                                                <th>{{ label3 }}</th>
                                            </tr> 
                                        </thead> -->
                                        <tbody>
                                            <tr v-for="unit2 in unit.formula" :key="unit2.expression">
                                                <!-- <td style="white-space: pre">{{ unit2.expression.replaceAll(";", "\n") }}
                                                </td>
                                                <td>{{ parsesum(unit2.expression) }}</td> -->

                                                <td v-if="unit2.expression" style="overflow-wrap: break-word;">{{
                                                    unit2.expression.replaceAll(";", "") }}</td>
                                                <td v-if="unit2.expression"
                                                    style="overflow-wrap: break-word;white-space: pre">{{
                                                    parsesum(unit2.expression) }}</td>


                                            </tr>


                                        </tbody>
                                    </table>
                                </td>
                                <td>{{ unit.rental }}</td>





                            </tr>
                        </tbody>
                    </table>
                    <div v-if="isImageModalVisible" class="image-modal" @click="closeImageModal">
                        <img :src="clickedImageUrl" class="full-image" />
                    </div>
                </td>
            </tr>
        </template>
    </div>
</template>

<script>
import { loadProjects } from '../utils/contactUtils.js';

import powerSlide from './powerSlide.vue'

export default {
    components: {
        powerSlide
    },
    props: {
        projectName: {
            type: String,
            required: true,
        },
    },
    data() {
        return {
            projects: [],
            expanded: false, // State to toggle extra fields
            isImageModalVisible: false,
            clickedImageUrl: '',
            label1: "Formula",
            label2: "Net Price",
            label3: ""

        };
    },
    async mounted() {
        await this.loadProjectsData(this.projectName);
    },


    methods: {
        splitLines(text) {
            return text ? text.split('\n') : [];
        },
        sanitizeKey(text) {
            return text ? text.substring(0, 20).replace(/[^a-z0-9]/gi, '_') : '';
        },
        isValidKValue(value) {
            if (value.toLowerCase().endsWith('k')) {
                const prefix = value.slice(0, -1); // Extract the part before 'k'
                if (!isNaN(prefix) && prefix.trim() !== '') {
                    return true; // Valid if prefix is numeric and not empty
                }
            }
            return false; // Invalid if it doesn't end with 'k' or prefix is not numeric
        },
        safeEvaluate(formula) {
            try {
                // Replace percentages with their decimal equivalents
                const sanitizedFormula = formula.replace(/(\d+\.?\d*)%/g, (match, p1) => {
                    return parseFloat(p1) / 100;
                });

                // Safely evaluate the sanitized formula
                // eslint-disable-next-line no-eval
                const computedValue = eval(sanitizedFormula);

                return computedValue;
            } catch (err) {
                console.error("Error evaluating formula:", err.message);
                return null;
            }
        },
        parsesum(ss) {
            try {
                // Reset error state
                this.error = null;

                // Ensure input is provided
                if (!ss) return;

                // Split the expression into variable assignments and computations
                const parts = ss.split(';');
                const assignments = parts[0].split(',').map(s => s.trim());
                const computations = parts[1].split(',').map(s => s.trim());

                // Object to store variables and intermediate results
                const variables = {};

                // Parse assignments
                assignments.forEach(assignment => {
                    const [variable, value] = assignment.split('=').map(s => s.trim());

                    if (this.isValidKValue(value)) {
                        // Handle 'k' notation (thousands)
                        variables[variable] = parseFloat(value.toLowerCase().replace('k', '')) * 1000;
                    } else if (value.endsWith('%')) {
                        // Handle percentage
                        variables[variable] = parseFloat(value.replace('%', '')) / 100;
                    } else if (isNaN(value)) {
                        // Handle formulas for intermediate variables
                        let formula = value;
                        for (const [varName, varValue] of Object.entries(variables)) {
                            formula = formula.replaceAll(varName, varValue);
                        }
                        // eslint-disable-next-line no-eval
                        variables[variable] = eval(formula);
                    } else {
                        // Handle regular numbers
                        variables[variable] = parseFloat(value);
                    }
                });

                // Process computations
                const results = computations.map(computation => {
                    let [label, formula] = computation.split(':').map(s => s.trim());

                    // Replace variables in the formula with their values
                    for (const [variable, value] of Object.entries(variables)) {
                        formula = formula.replaceAll(variable, value);
                    }

                    // Evaluate the formula
                    // eslint-disable-next-line no-eval
                    const computedValue = this.safeEvaluate(formula);

                    // Format monetary results as currency
                    if (label.toLowerCase().includes('price') || label.toLowerCase().includes('cashback') || label.toLowerCase().includes('installment')) {
                        return `${label}: ${new Intl.NumberFormat('en-US', {
                            style: 'currency',
                            currency: 'USD',
                        }).format(computedValue)}`;
                    } else if (label.toLowerCase().includes('interest')) {
                        return `${label}:${parseFloat(computedValue).toFixed(5)}`
                    } else {
                        // Return raw numerical results
                        return `${label}: ${computedValue}`;
                    }
                });

                // Combine results into a single string
                this.result = results.join('\n');
                return this.result;
            } catch (err) {
                this.error = `Failed to parse expression: ${err.message}`;
                alert(err.message);
                this.result = null;
            }
        },




        async loadProjectsData(projectFilter) {
            try {
                const projects = await loadProjects(projectFilter);
                console.log('Loaded projects:', projects);
                this.projects = projects;
            } catch (error) {
                console.error('Error loading projects:', error);
            }
        },
        showImageModal(url) {

            this.clickedImageUrl = url;
            this.isImageModalVisible = true;

        },
        closeImageModal() {
            this.isImageModalVisible = false;
        },
        toggleExpanded() {
            this.expanded = !this.expanded;
        },
        editProject(row) {
            console.log('Editing project:', row);
            // Implement your edit logic here
        },
        deleteProject(row) {
            console.log('Deleting project:', row);
            // Implement your delete logic here
        },
    },
    computed: {
    hasHighlights() {
      return this.projects.length > 0 && 
             this.projects[0].highLights && 
             this.projects[0].highLights.length > 0;
    }
  }
};
</script>

<style scoped>
/* Add these styles at the end of the existing style section */

/* Global left alignment */
table, p, h1, td, th, div {
    text-align: left;
}

/* Specific table adjustments */
table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 20px;
