<template>
    <div>
      <input 
        v-model="textToSpeak" 
        placeholder="Enter text to speak" 
        @keyup.enter="speakText"
      />
      <button @click="speakText">Speak</button>
      <select v-model="selectedVoice">
        <option 
          v-for="voice in voices" 
          :key="voice.name" 
          :value="voice"
        >
          {{ voice.name }} ({{ voice.lang }})
        </option>
      </select>
      <input 
        type="range" 
        min="0" 
        max="2" 
        step="0.1" 
        v-model="pitch"
      />
      <label>Pitch: {{ pitch }}</label>
      <input 
        type="range" 
        min="0.1" 
        max="10" 
        step="0.1" 
        v-model="rate"
      />
      <label>Rate: {{ rate }}</label>
    </div>
  </template>
  
  <script>
  import { ref, onMounted } from 'vue';
  
  export default {
    name: 'TextToSpeechComponent',
    setup() {
      const textToSpeak = ref('');
      const voices = ref([]);
      const selectedVoice = ref(null);
      const pitch = ref(1);
      const rate = ref(1);
  
      const speakText = () => {
        if (!textToSpeak.value) return;
  
        const utterance = new SpeechSynthesisUtterance(textToSpeak.value);
        utterance.voice = selectedVoice.value;
        utterance.pitch = parseFloat(pitch.value);
        utterance.rate = parseFloat(rate.value);
  
        window.speechSynthesis.speak(utterance);
      };
  
      const updateVoices = () => {
        voices.value = window.speechSynthesis.getVoices();
        if (voices.value.length > 0) {
          selectedVoice.value = voices.value[0];
        }
      };
  
      onMounted(() => {
        // Load voices when the component mounts
        updateVoices();
        
        // Some browsers load voices asynchronously, so we listen for changes
        window.speechSynthesis.onvoiceschanged = updateVoices;
      });
  
      return {
        textToSpeak,
        voices,
        selectedVoice,
        pitch,
        rate,
        speakText
      };
    }
  }
  </script>
  
  <style scoped>
    /* Add some styling for better visual feedback */
    div {
      margin: 20px;
    }
    input[type="range"] {
      width: 100%;
    }
  </style>